const data = $input.first().json;
const orderNumber = data.orderNumber || 'Unknown';
const amount = data.amount || 0;
const customerEmail = data.customerEmail || 'N/A';

const formattedAmount = new Intl.NumberFormat('id-ID', {
  style: 'currency',
  currency: 'IDR',
  minimumFractionDigits: 0
}).format(amount);

const notification = {
  subject: `Payment Confirmed - Order ${orderNumber}`,
  body: `Hello!

Your payment has been confirmed.

Order Number: ${orderNumber}
Amount: ${formattedAmount}
Customer Email: ${customerEmail}

Thank you for your purchase!

Best regards,
UMKM ERP Team`,
  customerEmail: customerEmail,
  orderNumber: orderNumber,
  amount: formattedAmount
};

return [{ json: notification }];

const data = $input.first().json;
console.log('=== PAYMENT NOTIFICATION ===');
console.log('Order:', data.orderNumber);
console.log('Amount:', data.amount);
console.log('Customer:', data.customerEmail);
console.log('Subject:', data.subject);
console.log('============================');

return [{ json: { ...data, sentAt: new Date().toISOString(), status: 'logged' } }];
